CREATE TABLE crops(`id` bigint  UNSIGNED PRIMARY KEY AUTO_INCREMENT,`created_at` timestamp  DEFAULT CURRENT_TIMESTAMP NOT NULL,`updated_at` timestamp  DEFAULT CURRENT_TIMESTAMP ON UPDATE CURRENT_TIMESTAMP NOT NULL,`enable` TINYINT(1)  NOT NULL  DEFAULT 1 ,`farm_plot_id` bigint  NOT NULL,`strategy_id` bigint  NULL COMMENT 'Link to annual strategy',`crop_name` varchar(255)  NOT NULL,`crop_variety` varchar(255)  NULL,`season` varchar(255)  NOT NULL COMMENT 'kharif, rabi, zaid',`planting_date` date  NOT NULL,`expected_harvest_date` date  NOT NULL,`area` DECIMAL(10,2)  NOT NULL COMMENT 'Area in acres',`expected_yield` DECIMAL(12,2)  NULL COMMENT 'Expected yield in kg',`expected_profit` DECIMAL(12,2)  NULL,`actual_yield` DECIMAL(12,2)  NULL COMMENT 'Actual yield in kg',`actual_profit` DECIMAL(12,2)  NULL,`status` varchar(255)  DEFAULT 'planned' COMMENT 'planned, planted, growing, harvested')ENGINE = InnoDB AUTO_INCREMENT = 1 DEFAULT CHARSET = utf8;